cardStylesheet:
/*
  The card print contract. This is the card design itself, owned by the generator and
  embedded into every emitted card, rather than a stylesheet the output links to.
  The typeface declarations are not here. A card names its families and the page it is
  embedded into provides them, the same way any component relies on a page's web fonts.
*/
/* Reusable late-Gen-1 card coordinate and print contract. */
:root {
  --blokemon-card-w: 750px;
  --blokemon-card-h: 1050px;
  --blokemon-outer-border: 25px;
  --blokemon-inner-x: 25px;
  --blokemon-inner-y: 25px;
  --blokemon-inner-w: 700px;
  --blokemon-inner-h: 999px;
  --blokemon-header-y: 40px;
  --blokemon-header-h: 65px;
  --blokemon-art-frame-x: 64px;
  --blokemon-art-frame-y: 109px;
  --blokemon-art-frame-w: 621px;
  --blokemon-art-frame-h: 449px;
  --blokemon-art-x: 79px;
  --blokemon-art-y: 123px;
  --blokemon-art-w: 590px;
  --blokemon-art-h: 416px;
  --blokemon-meta-y: 563px;
  --blokemon-meta-h: 36px;
  --blokemon-rules-x: 42px;
  --blokemon-rules-y: 606px;
  --blokemon-rules-w: 664px;
  --blokemon-rules-h: 261px;
  --blokemon-energy-x: 42px;
  --blokemon-copy-x: 110px;
  --blokemon-damage-x: 608px;
  --blokemon-footer-y: 868px;
  --blokemon-stat-y: 874px;
  --blokemon-stat-h: 66px;
  --blokemon-flavour-y: 948px;
  --blokemon-flavour-h: 47px;
  --blokemon-legal-y: 997px;
  --blokemon-legal-h: 28px;
  --blokemon-card-scale: 1;

  --blokemon-face: "Gillius ADF", sans-serif;
  --blokemon-numeric-face: "Jost", sans-serif;
}

/*
  Type theme hook. Every card carries data-card-type derived from its own card data, so a new type
  is a token block rather than a second card implementation. A theme owns only print colour and
  atmosphere; it never moves a canonical coordinate, changes mechanics hierarchy or covers artwork.

  --tt-haze / --tt-cream   readable near-white centre the text sits on
  --tt-mid / --tt-deep     field colour and darkest edge
  --tt-glow                warm accent bloom
  --tt-smoke-hi/mid        dense and thin themed smoke used by the field plume layers
  --tt-lift                bright break in the smoke, the airbrushed highlight
  --tt-ink                 thin printed rule ink
  --tt-pip / --tt-pip-rim  Attack Energy disc
  --tt-icon                main type disc
  --tt-frame-hi/lo         art frame and strip cardstock
  --tt-flavour-rule        flavour box hairline
*/
.blokemon-gym-card {
  --tt-haze: #fbf8ea;
  --tt-cream: #efe9cd;
  --tt-mid: #bdb797;
  --tt-deep: #8d886b;
  --tt-edge: rgba(72, 70, 46, .34);
  --tt-glow: rgba(214, 176, 96, .46);
  --tt-smoke-hi: rgba(108, 110, 82, .62);
  --tt-smoke-mid: rgba(126, 128, 96, .38);
  --tt-lift: rgba(252, 248, 228, .66);
  --tt-ink: #1f2410;
  --tt-pip: #b9b391;
  --tt-pip-rim: #6d684c;
  --tt-icon: #b3ad8c;
  --tt-frame-hi: #ffec92;
  --tt-frame-lo: #dcb038;
  --tt-flavour-rule: rgba(122, 92, 44, .8);
  --blokemon-lead-label: #1f3f8c;
  --blokemon-lead-name: #a2331b;
}

/* Blazed: layered sage/olive smoke plumes over hazy cream with a muted amber bloom. */
.blokemon-gym-card[data-card-type="Blazed"] {
  --tt-haze: #fdfae4;
  --tt-cream: #f3f1ac;
  --tt-mid: #b3ca5a;
  --tt-deep: #4f7620;
  --tt-edge: rgba(64, 92, 14, .44);
  --tt-glow: rgba(233, 150, 24, .68);
  --tt-smoke-hi: rgba(86, 126, 26, .84);
  --tt-smoke-mid: rgba(152, 182, 68, .58);
  --tt-lift: rgba(255, 252, 220, .80);
  --tt-pip: #93a95c;
  --tt-pip-rim: #4d5a2c;
  --tt-icon: #8fa955;
  --tt-frame-hi: #eccd6d;
  --tt-frame-lo: #b8963c;
  --tt-flavour-rule: rgba(150, 82, 30, .85);
}

/* Curry: turmeric, orange and brick marbling under an oily curry sheen. */
.blokemon-gym-card[data-card-type="Curry"] {
  --tt-haze: #fdf6e4;
  --tt-cream: #fbe3b4;
  --tt-mid: #eb9a48;
  --tt-deep: #b5451e;
  --tt-edge: rgba(150,58,10,.44);
  --tt-glow: rgba(250,194,68,.62);
  --tt-smoke-hi: rgba(184,70,24,.74);
  --tt-smoke-mid: rgba(232,140,60,.52);
  --tt-lift: rgba(255,250,228,.78);
  --tt-pip: #e08a3c;
  --tt-pip-rim: #8a3a12;
  --tt-icon: #dd7a34;
  --tt-flavour-rule: rgba(150,52,20,.85);
}
/* Sober: cool morning blue and steel with a clean pale wash. */
.blokemon-gym-card[data-card-type="Sober"] {
  --tt-haze: #f2fafe;
  --tt-cream: #d6ebf8;
  --tt-mid: #7cb2d7;
  --tt-deep: #33668d;
  --tt-edge: rgba(18,62,98,.44);
  --tt-glow: rgba(142,208,234,.55);
  --tt-smoke-hi: rgba(42,106,154,.72);
  --tt-smoke-mid: rgba(120,176,214,.50);
  --tt-lift: rgba(250,254,255,.80);
  --tt-pip: #6aa5cc;
  --tt-pip-rim: #2b5a80;
  --tt-icon: #6aa5cc;
  --tt-flavour-rule: rgba(28,82,122,.85);
}
/* Beer: warm amber and foam over a golden pour. */
.blokemon-gym-card[data-card-type="Beer"] {
  --tt-haze: #fffbe2;
  --tt-cream: #fbeeae;
  --tt-mid: #eac63f;
  --tt-deep: #a97d0e;
  --tt-edge: rgba(120,86,6,.46);
  --tt-glow: rgba(255,228,116,.60);
  --tt-smoke-hi: rgba(176,128,14,.70);
  --tt-smoke-mid: rgba(238,204,84,.52);
  --tt-lift: rgba(255,253,232,.80);
  --tt-pip: #edc63f;
  --tt-pip-rim: #8d6708;
  --tt-icon: #eabf34;
  --tt-flavour-rule: rgba(140,100,12,.85);
}
/* Geeked: violet haze and magenta bloom. */
.blokemon-gym-card[data-card-type="Geeked"] {
  --tt-haze: #fbf4fd;
  --tt-cream: #ecd9f3;
  --tt-mid: #b085c6;
  --tt-deep: #6a3888;
  --tt-edge: rgba(72,26,102,.44);
  --tt-glow: rgba(226,148,214,.55);
  --tt-smoke-hi: rgba(100,48,128,.72);
  --tt-smoke-mid: rgba(172,124,196,.50);
  --tt-lift: rgba(253,248,255,.80);
  --tt-pip: #a87ac2;
  --tt-pip-rim: #5d3078;
  --tt-icon: #a87ac2;
  --tt-flavour-rule: rgba(94,42,122,.85);
}
/* Lairy: punch-impact bursts and ink shock lines in bruised crimson and cobalt. */
.blokemon-gym-card[data-card-type="Lairy"] {
  --tt-haze: #fdf2ef;
  --tt-cream: #f5d7cf;
  --tt-mid: #ca6b59;
  --tt-deep: #872724;
  --tt-edge: rgba(96,20,20,.46);
  --tt-glow: rgba(64,88,176,.50);
  --tt-smoke-hi: rgba(122,28,30,.74);
  --tt-smoke-mid: rgba(196,92,74,.50);
  --tt-lift: rgba(255,248,244,.78);
  --tt-pip: #c4573f;
  --tt-pip-rim: #7c2418;
  --tt-icon: #c4573f;
  --tt-flavour-rule: rgba(138,38,30,.85);
}
/* Dodgy: slate green-black murk with a low sodium glow. */
.blokemon-gym-card[data-card-type="Dodgy"] {
  --tt-haze: #f2f3ed;
  --tt-cream: #d7dad0;
  --tt-mid: #7a8276;
  --tt-deep: #313a34;
  --tt-edge: rgba(20,28,22,.48);
  --tt-glow: rgba(154,170,118,.44);
  --tt-smoke-hi: rgba(34,44,38,.74);
  --tt-smoke-mid: rgba(96,106,94,.52);
  --tt-lift: rgba(248,250,242,.74);
  --tt-pip: #6f7a6c;
  --tt-pip-rim: #2b332d;
  --tt-icon: #6f7a6c;
  --tt-flavour-rule: rgba(46,56,48,.85);
}
/* Local: warm neutral cream and dust, the plain-clothes field. */
.blokemon-gym-card[data-card-type="Local"] {
  --tt-haze: #fdfaef;
  --tt-cream: #ede5d0;
  --tt-mid: #c1b7a0;
  --tt-deep: #877c65;
  --tt-edge: rgba(74,64,42,.40);
  --tt-glow: rgba(216,188,130,.48);
  --tt-smoke-hi: rgba(122,110,86,.62);
  --tt-smoke-mid: rgba(178,166,142,.46);
  --tt-lift: rgba(255,252,242,.78);
  --tt-pip: #bdb298;
  --tt-pip-rim: #6f6650;
  --tt-icon: #bdb298;
  --tt-flavour-rule: rgba(118,98,64,.80);
}
/* Legend: deep bronze and regal gold. */
.blokemon-gym-card[data-card-type="Legend"] {
  --tt-haze: #fdf8e6;
  --tt-cream: #f1e2b2;
  --tt-mid: #c7a340;
  --tt-deep: #795911;
  --tt-edge: rgba(88,62,8,.46);
  --tt-glow: rgba(255,222,122,.58);
  --tt-smoke-hi: rgba(108,78,12,.72);
  --tt-smoke-mid: rgba(196,164,72,.50);
  --tt-lift: rgba(255,252,234,.80);
  --tt-pip: #cfae4e;
  --tt-pip-rim: #7a5a10;
  --tt-icon: #cfae4e;
  --tt-flavour-rule: rgba(118,86,16,.85);
}

/*
  A card is embedded into pages the generator does not control, and host rules on bare element
  selectors cascade straight into it. Everything the design sets is re-declared below, so the reset
  only has to neutralise what a host might set on a p, h2, b, small or img.
*/
.blokemon-gym-card,
.blokemon-gym-card *,
.blokemon-gym-card *::before,
.blokemon-gym-card *::after {
  margin: 0;
  padding: 0;
  max-width: none;
  min-width: 0;
  max-height: none;
  min-height: 0;
  float: none;
  text-indent: 0;
  text-transform: none;
  text-decoration: none;
  list-style: none;
  font: inherit;
  letter-spacing: normal;
  word-spacing: normal;
  vertical-align: baseline;
}

.blokemon-card-scale {
  position: relative;
  width: calc(var(--blokemon-card-w) * var(--blokemon-card-scale));
  height: calc(var(--blokemon-card-h) * var(--blokemon-card-scale));
  flex: 0 0 auto;
}

/*
  Shallow printed cardstock. The measured 750 x 1050 face is the card authority: the bevel is a
  1.5 px inset highlight on the yellow border, the paper thickness is 2 px of warm edge under the
  silhouette, and the lift is one soft low-opacity ambient shadow. No side slab, offset silhouette,
  raised nested plate, perspective or foil sweep.
*/
.blokemon-gym-card {
  position: absolute;
  inset: 0 auto auto 0;
  width: var(--blokemon-card-w);
  height: var(--blokemon-card-h);
  transform: scale(var(--blokemon-card-scale));
  transform-origin: 0 0;
  border: 0;
  outline: 1px solid rgba(44, 36, 16, .85);
  outline-offset: -1px;
  border-radius: 20px;
  background:
    radial-gradient(circle at 1px 1px, rgba(122, 94, 26, .06) 0 .7px, rgba(255, 255, 255, 0) 1.2px) 0 0 / 4px 4px,
    linear-gradient(178deg, #f9da5c 0%, #f5d452 46%, #f0cd47 78%, #e8c33d 100%);
  color: #16120a;
  box-shadow:
    inset 0 1.5px 0 rgba(255, 252, 226, .85),
    inset 1.5px 0 0 rgba(255, 250, 220, .50),
    inset -1.5px 0 0 rgba(146, 110, 26, .45),
    inset 0 -2px 0 rgba(132, 100, 24, .55),
    0 1px 0 rgba(150, 118, 42, .95),
    0 2px 0 rgba(104, 80, 28, .70),
    0 3px 2px rgba(52, 42, 18, .26),
    0 9px 18px -5px rgba(38, 32, 14, .28);
  font-family: var(--blokemon-face);
  line-height: 1.15;
  contain: layout style;
}

.blokemon-gym-card,
.blokemon-gym-card * { box-sizing: border-box; }

/*
  Printed inner field. Layer order top to bottom: halftone dot screen, paper fibre grain, drifting
  smoke plumes, warm amber bloom, readable haze over the header/rules bands, then the base wash.
*/
.blokemon-gym-card .printed-inner-field {
  position: absolute;
  left: var(--blokemon-inner-x);
  top: var(--blokemon-inner-y);
  width: var(--blokemon-inner-w);
  height: var(--blokemon-inner-h);
  border: 2px solid var(--tt-ink);
  border-radius: 11px;
  background-image:
    radial-gradient(circle at 1px 1px, rgba(52, 62, 20, .07) 0 .7px, rgba(255, 255, 255, 0) 1.15px),
    radial-gradient(circle at 3px 5px, rgba(70, 82, 26, .04) 0 1.3px, rgba(255, 255, 255, 0) 2.1px),
    radial-gradient(circle at 9px 4px, rgba(255, 252, 216, .10) 0 1.7px, rgba(255, 255, 255, 0) 2.6px),
    radial-gradient(19% 8% at 34% 12%, var(--tt-lift) 0%, rgba(255, 255, 255, 0) 76%),
    radial-gradient(15% 5% at 26% 61%, var(--tt-lift) 0%, rgba(255, 255, 255, 0) 78%),
    radial-gradient(38% 16% at 6% 5%, var(--tt-smoke-hi) 0%, var(--tt-smoke-mid) 44%, rgba(255, 255, 255, 0) 78%),
    radial-gradient(30% 12% at 40% 2%, var(--tt-glow) 0%, rgba(255, 255, 255, 0) 74%),
    radial-gradient(36% 17% at 94% 6%, var(--tt-smoke-hi) 0%, var(--tt-smoke-mid) 46%, rgba(255, 255, 255, 0) 78%),
    radial-gradient(23% 18% at 1% 23%, var(--tt-smoke-hi) 0%, var(--tt-smoke-mid) 48%, rgba(255, 255, 255, 0) 78%),
    radial-gradient(9% 20% at 1% 33%, var(--tt-smoke-hi) 0%, rgba(255, 255, 255, 0) 74%),
    radial-gradient(9% 20% at 99% 36%, var(--tt-smoke-hi) 0%, rgba(255, 255, 255, 0) 74%),
    radial-gradient(40% 5% at 50% 9%, var(--tt-smoke-hi) 0%, rgba(255, 255, 255, 0) 76%),
    radial-gradient(44% 5% at 48% 53%, var(--tt-smoke-hi) 0%, rgba(255, 255, 255, 0) 78%),
    radial-gradient(21% 16% at 100% 27%, var(--tt-smoke-hi) 0%, var(--tt-smoke-mid) 48%, rgba(255, 255, 255, 0) 78%),
    radial-gradient(19% 14% at 2% 45%, var(--tt-glow) 0%, rgba(255, 255, 255, 0) 76%),
    radial-gradient(20% 15% at 99% 47%, var(--tt-smoke-hi) 0%, var(--tt-smoke-mid) 50%, rgba(255, 255, 255, 0) 78%),
    radial-gradient(34% 8% at 46% 56%, var(--tt-smoke-mid) 0%, rgba(255, 255, 255, 0) 80%),
    radial-gradient(24% 6% at 13% 60%, var(--tt-smoke-mid) 0%, rgba(255, 255, 255, 0) 78%),
    radial-gradient(21% 5% at 69% 62%, var(--tt-smoke-mid) 0%, rgba(255, 255, 255, 0) 78%),
