.blokemon-gym-card .previous-art {
  position: absolute;
  z-index: 2;
  left: 24px;
  top: 33px;
  /* Laid out at the size it is seen at and scaled back, as the illustration above is, so that a
     thumbnail this small is not sent the full-size picture. */
  width: calc(74px * var(--blokemon-card-scale));
  height: calc(52px * var(--blokemon-card-scale));
  transform: scale(calc(1 / var(--blokemon-card-scale)));
  transform-origin: 0 0;
  object-fit: contain;
  object-position: center;
  border: 0;
  background: linear-gradient(168deg, #a3b4bb 0%, #93a5ad 62%, #85979f 100%);
}

.blokemon-gym-card .art-frame {
  position: absolute;
  left: var(--blokemon-art-frame-x);
  top: var(--blokemon-art-frame-y);
  width: var(--blokemon-art-frame-w);
  height: var(--blokemon-art-frame-h);
  z-index: 2;
  border: 0;
  background:
    linear-gradient(158deg, var(--tt-frame-hi) 0%, #f7d95e 46%, var(--tt-frame-lo) 100%);
  box-shadow:
    inset 2px 2px 0 rgba(255, 253, 226, .85),
    inset -2px -2px 0 rgba(150, 112, 24, .55),
    5px 5px 6px -1px rgba(38, 28, 6, .45);
}

.blokemon-gym-card .art-frame::before,
.blokemon-gym-card .art-frame::after {
  content: "";
  position: absolute;
  pointer-events: none;
}

/* Thin printed rules around the art, not a raised picture frame. */
.blokemon-gym-card .art-frame::before {
  inset: 7px;
  border: 1px solid rgba(140, 104, 24, .55);
  box-shadow: 0 0 0 1px rgba(255, 251, 216, .45);
}

.blokemon-gym-card .art-frame::after {
  left: 13px;
  top: 12px;
  width: 592px;
  height: 418px;
  border: 1px solid #14140e;
  box-shadow:
    inset 2px 2px 4px rgba(26, 22, 8, .50),
    inset -1px -1px 0 rgba(255, 250, 214, .30),
    0 0 0 1px rgba(255, 248, 208, .40);
}

.blokemon-gym-card .art-viewport {
  position: absolute;
  left: var(--blokemon-art-x);
  top: var(--blokemon-art-y);
  z-index: 3;
  width: var(--blokemon-art-w);
  height: var(--blokemon-art-h);
  margin: 0;
  border: 0;
  background: #2b3122;
}

.blokemon-gym-card .art-viewport img {
  display: block;
  /*
    Laid out at the size its responsive artwork was selected for, and scaled back up by the
    inverse of that scale so that it paints in exactly the same place at exactly the same size.

    The card is a fixed 750 x 1050 grid shrunk by a transform, and a transform is a painting
    operation: it never touches layout. An illustration written the obvious way is therefore laid
    out at its full 590 however small the card is drawn, and `sizes="auto"` - which reads the
    layout box - would ask for the largest picture for a tile an inch across. Inverting the scale
    here is what makes the box the browser measures the box the player actually sees, without
    moving a single canonical coordinate of the card. A full-size viewer keeps this selection
    scale at the originating face's value, so expanding a card retains the already loaded source
    while the card's visual scale changes independently.

    Still a percentage of the viewport rather than a measurement of its own: the viewport is a
    different size for a framed illustration, a full-bleed reverse and an energy field, and the
    illustration has always taken whichever it is put in.
  */
  width: calc(100% * var(--blokemon-artwork-scale, var(--blokemon-card-scale)));
  height: calc(100% * var(--blokemon-artwork-scale, var(--blokemon-card-scale)));
  transform: scale(calc(1 / var(--blokemon-artwork-scale, var(--blokemon-card-scale))));
  transform-origin: 0 0;
  object-fit: contain;
  object-position: center;
  /*
    The card travels with a few hundred bytes of its own illustration, set as this element's
    background, so that the space the picture will fill is never an empty rectangle while it is on
    the way. These three lay it out in exactly the box object-fit puts the picture in, so that
    arriving replaces it rather than uncovering it, and it says nothing at all about how a card
    looks once its illustration is here.
  */
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
}

.blokemon-gym-card .metadata-strip {
  position: absolute;
  left: 79px;
  top: var(--blokemon-meta-y);
  z-index: 3;
  width: 590px;
  height: var(--blokemon-meta-h);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 12px;
  border: 0;
  border-radius: 2px;
  /* Vertical sheen over the horizontal foil. */
  background:
    linear-gradient(
      180deg,
      rgba(255, 255, 246, .42) 0%,
      rgba(255, 255, 246, .10) 34%,
      rgba(255, 255, 255, 0) 52%,
      rgba(176, 128, 24, .12) 100%
    ),
    linear-gradient(
      90deg,
      #eec244 0%,
      #eec244 33.33%,
      #fff0a6 50%,
      #eec244 66.67%,
      #eec244 100%
    );
  box-shadow:
    inset 0 1.5px 0 rgba(255, 255, 244, .98),
    inset 0 -1px 0 rgba(255, 242, 178, .70),
    0 1px 2px rgba(78, 56, 10, .32);
  font: italic 700 20px/22px var(--blokemon-face);
  text-align: center;
  color: #241d0c;
}

.blokemon-gym-card .rules-flow {
  position: absolute;
  left: var(--blokemon-rules-x);
  top: var(--blokemon-rules-y);
  z-index: 3;
  width: var(--blokemon-rules-w);
  height: var(--blokemon-rules-h);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  border-top: 1px solid rgba(35, 30, 12, .42);
  overflow: visible;
}

/* Entries size from their own content. The divider sits between entries, never after the last. */
.blokemon-gym-card .rule-entry {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: 68px minmax(0,1fr) 96px;
  align-items: center;
  min-width: 0;
  padding: 7px 0 8px;
}

.blokemon-gym-card .rule-entry + .rule-entry { border-top: 2px solid var(--tt-ink); }

/* Blokemon Power and Rule keep the Attack grid and share its copy margin; their Energy gutter is blank. */

.blokemon-gym-card .entry-energy {
  grid-column: 1;
  display: grid;
  grid-template-columns: repeat(2, 26px);
  grid-auto-rows: 38px;
  justify-items: start;
  width: 62px;
}

.blokemon-gym-card .energy-pip {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border: 2px solid var(--disc-rim, var(--tt-pip-rim));
  border-radius: 50%;
  background:
    radial-gradient(circle at 34% 26%, rgba(255, 255, 234, .8) 0%, rgba(255, 255, 234, 0) 48%),
    radial-gradient(circle at 50% 60%, var(--disc, var(--tt-pip)) 0%, var(--disc-rim, var(--tt-pip-rim)) 118%);
  box-shadow: inset 0 0 0 1.5px rgba(255, 253, 226, .60), inset 0 -2px 3px rgba(34, 40, 18, .34);
  font: 700 13px/1 var(--blokemon-face);
  color: #14180d;
}


.blokemon-gym-card .entry-copy {
  grid-column: 2;
  min-width: 0;
  margin: 0;
  padding: 1px 8px 0 0;
  font: 19px/21.5px var(--blokemon-face);
  color: #17140a;
}

.blokemon-gym-card .entry-copy.is-name-only {
  text-align: center;
}

.blokemon-gym-card .entry-copy.is-name-only .entry-name {
  margin-right: 0;
}

.blokemon-gym-card .rule-entry.is-note .entry-copy {
  grid-column: 2 / 4;
  padding-right: 4px;
}

/* Attack identity comes from Energy, a bold printed name and Damage, never a repeated pill. */
.blokemon-gym-card .entry-name {
  margin-right: 7px;
  font: 700 25px/27px var(--blokemon-face);
  letter-spacing: -.008em;
  color: #14100a;
  text-shadow: .5px .4px 0 rgba(168, 60, 30, .16);
}

/* Period coloured inline lead-in for Blokemon Power and Rule entries. */
.blokemon-gym-card .entry-lead {
  margin-right: 6px;
  font: 700 21px/24px var(--blokemon-face);
  color: var(--blokemon-lead-label);
}

.blokemon-gym-card .rule-entry.is-note .entry-name { color: var(--blokemon-lead-name); font-size: 21px; line-height: 24px; }

.blokemon-gym-card .entry-damage {
  grid-column: 3;
  justify-self: end;
  width: 96px;
  padding-right: 6px;
  text-align: right;
  font: 900 34px/36px var(--blokemon-numeric-face);
  white-space: nowrap;
  color: #14100a;
  text-shadow: 0 1px 0 rgba(255, 252, 226, .55);
}

.blokemon-gym-card .footer-rule {
  position: absolute;
  left: 42px;
  top: var(--blokemon-footer-y);
  z-index: 3;
  width: 664px;
  border-top: 2px solid var(--tt-ink);
}

/* Compact late-Gen-1 weakness / resistance / retreat composition in one printed row. */
.blokemon-gym-card .stat-row {
  position: absolute;
  left: 42px;
  top: var(--blokemon-stat-y);
  z-index: 3;
  width: 664px;
  height: var(--blokemon-stat-h);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

.blokemon-gym-card .footer-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  min-width: 0;
  padding-top: 3px;
}

.blokemon-gym-card .footer-stat b {
  font: 700 16px/18px var(--blokemon-face);
  color: #241d0c;
}

.blokemon-gym-card .stat-value {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font: 700 14px/16px var(--blokemon-face);
  white-space: nowrap;
  color: #1d1a0b;
}

.blokemon-gym-card .footer-icon {
  flex: 0 0 29px;
  width: 29px;
  height: 29px;
  display: grid;
  place-items: center;
  border: 1.5px solid var(--tt-ink);
  border-radius: 50%;
  background:
    radial-gradient(circle at 34% 26%, rgba(255, 255, 234, .8) 0%, rgba(255, 255, 234, 0) 48%),
    radial-gradient(circle at 50% 60%, var(--disc, #d78046) 0%, var(--disc-rim, #a1481f) 116%);
  box-shadow: inset 0 0 0 1.5px rgba(255, 250, 226, .55);
  font: 700 11px/1 var(--blokemon-face);
  color: #2b1109;
}


/* Boxed printed flavour line, the period plate above the illustrator/rarity row. */
.blokemon-gym-card .flavour-box {
  position: absolute;
  left: 42px;
  top: var(--blokemon-flavour-y);
  z-index: 3;
  width: 664px;
  height: var(--blokemon-flavour-h);
  display: flex;
  align-items: center;
  padding: 4px 11px;
  border: 1px solid var(--tt-flavour-rule);
  border-radius: 2px;
  background: linear-gradient(180deg, rgba(255, 253, 232, .42), rgba(255, 250, 218, .22));
  box-shadow: inset 0 0 0 1px rgba(255, 253, 228, .45);
}

.blokemon-gym-card .flavour {
  min-width: 0;
  margin: 0;
  font: italic 400 14px/16.5px var(--blokemon-face);
  color: #221b0a;
}

.blokemon-gym-card .card-index { font-style: normal; }

.blokemon-gym-card .legal-row {
  position: absolute;
  left: 42px;
  top: var(--blokemon-legal-y);
  z-index: 3;
  width: 664px;
  height: var(--blokemon-legal-h);
  display: grid;
  grid-auto-flow: column;
  justify-content: end;
  align-items: center;
  gap: 9px;
  padding: 0 2px;
  font: 400 10px/12px var(--blokemon-face);
  color: #2a230e;
}

.blokemon-gym-card .rarity-mark {
  width: 20px;
  height: 20px;
  display: grid;
  place-items: center;
  font-size: 13px;
  line-height: 1;
  color: #241d0c;
}

/* Only whole-card scale changes. Internal coordinates never reflow. */
.blokemon-gym-card[data-layout="gym-challenge-750x1050"] { --blokemon-layout-version: "D237"; }

/* Lairy adds radiating impact shock lines from two bruise points. */
.blokemon-gym-card[data-card-type="Lairy"] .printed-inner-field::after {
  background-image:
    repeating-conic-gradient(from 8deg at 21% 26%, rgba(122, 28, 30, .07) 0 2deg, rgba(255, 255, 255, 0) 2deg 19deg),
    repeating-conic-gradient(from 22deg at 78% 74%, rgba(52, 74, 156, .06) 0 2deg, rgba(255, 255, 255, 0) 2deg 23deg),
    radial-gradient(34% 8% at 32% 30%, var(--tt-smoke-hi) 0%, rgba(255, 255, 255, 0) 74%),
    radial-gradient(30% 7% at 70% 70%, var(--tt-glow) 0%, rgba(255, 255, 255, 0) 76%);
  opacity: .62;
}

/* Curry adds oily marbling and a few separated droplets. */
.blokemon-gym-card[data-card-type="Curry"] .printed-inner-field::after {
  background-image:
    radial-gradient(circle at 6px 4px, rgba(120, 48, 8, .16) 0 2px, rgba(255, 255, 255, 0) 3.2px),
    radial-gradient(52% 5% at 30% 22%, var(--tt-smoke-hi) 0%, rgba(255, 255, 255, 0) 76%),
    radial-gradient(46% 4% at 66% 38%, var(--tt-glow) 0%, rgba(255, 255, 255, 0) 78%),
    radial-gradient(56% 5% at 40% 63%, var(--tt-smoke-mid) 0%, rgba(255, 255, 255, 0) 78%),
    radial-gradient(44% 4% at 68% 84%, var(--tt-smoke-hi) 0%, rgba(255, 255, 255, 0) 78%);
  background-size: 23px 19px, auto, auto, auto, auto;
  opacity: .74;
}

/* Trainer: no HP, type disc, evolution or stat row. Its rules region runs to the flavour plate. */
.blokemon-gym-card[data-card-type="Trainer"] {
  --tt-haze: #fdfaef;
  --tt-cream: #f0e6cc;
  --tt-mid: #c9b285;
  --tt-deep: #8a6c3c;
  --tt-edge: rgba(84, 60, 20, .42);
  --tt-glow: rgba(226, 190, 116, .50);
  --tt-smoke-hi: rgba(132, 100, 48, .62);
  --tt-smoke-mid: rgba(186, 158, 112, .46);
  --tt-lift: rgba(255, 252, 240, .78);
  --tt-pip: #c3ad84;
  --tt-pip-rim: #6f5730;
  --tt-icon: #c3ad84;
  --tt-flavour-rule: rgba(122, 88, 34, .82);
}

.blokemon-gym-card:not(:has(.stat-row)) .rules-flow { height: 341px; }

.blokemon-gym-card:not(:has(.hp-cluster)) .card-name { width: 580px; font-size: min(44px, calc(580px / (var(--blokemon-name-len, 12) * .68))); }

.blokemon-gym-card:not(:has(.rules-flow)) .metadata-strip { top: 640px; }
.blokemon-gym-card:not(:has(.rules-flow)) .flavour-box { top: 700px; height: 120px; }
.blokemon-gym-card:not(:has(.rules-flow)) .flavour { font-size: 17px; line-height: 22px; }

/* Reverse: one full-bleed printed face inside the same silhouette. */
.blokemon-gym-card .art-viewport[data-placement="full-bleed"] {
  left: 0;
  top: 0;
  width: var(--blokemon-card-w);
  height: var(--blokemon-card-h);
  border-radius: 20px;
  overflow: hidden;
  background: none;
}

.blokemon-gym-card .art-viewport[data-placement="full-bleed"] img { object-fit: cover; }

.blokemon-gym-card .type-glyph-sprite { position: absolute; width: 0; height: 0; overflow: hidden; }

.blokemon-gym-card .main-type-icon .type-glyph { width: 39px; height: 39px; }
.blokemon-gym-card .energy-pip .type-glyph { width: 29px; height: 29px; }
.blokemon-gym-card .footer-icon .type-glyph { width: 23px; height: 23px; }
.blokemon-gym-card .type-glyph { display: block; filter: drop-shadow(0 1px 0 rgba(255, 252, 224, .35)); }

.blokemon-gym-card [data-energy="Blazed"] { --disc: #a7c25c; --disc-rim: #4d5a2c; }
.blokemon-gym-card [data-energy="Beer"] { --disc: #f0cc3c; --disc-rim: #8d6708; }
.blokemon-gym-card [data-energy="Curry"] { --disc: #e08a44; --disc-rim: #8a3a12; }
.blokemon-gym-card [data-energy="Dodgy"] { --disc: #8e988d; --disc-rim: #2b332d; }
.blokemon-gym-card [data-energy="Geeked"] { --disc: #b184cc; --disc-rim: #5d3078; }
.blokemon-gym-card [data-energy="Lairy"] { --disc: #d16b4e; --disc-rim: #7c2418; }
.blokemon-gym-card [data-energy="Legend"] { --disc: #d9b849; --disc-rim: #7a5a10; }
.blokemon-gym-card [data-energy="Local"] { --disc: #e2dcc0; --disc-rim: #7a7355; }
.blokemon-gym-card [data-energy="Roadie"] { --disc: #a5aeb5; --disc-rim: #454b50; }
.blokemon-gym-card [data-energy="Sober"] { --disc: #6fadd6; --disc-rim: #2b5a80; }

/*
  Holo foil. Edition 1 confines the foil to the illustration window: the printed frame, the copy
  and the imprint row all stay matte, so only the art reads as holographic.

  A polished sheen under the ink plus one travelling glint. Both layers are oversized and driven
  by transform so the rock runs on the compositor rather than repainting the window.
*/
.blokemon-gym-card[data-holo] .art-viewport[data-placement="framed"] {
  overflow: hidden;
}

.blokemon-gym-card[data-holo] .art-viewport[data-placement="framed"]::before,
.blokemon-gym-card[data-holo] .art-viewport[data-placement="framed"]::after {
  content: "";
  position: absolute;
  inset: -30%;
  z-index: 2;
  pointer-events: none;
  will-change: transform;
}

.blokemon-gym-card[data-holo] .art-viewport[data-placement="framed"]::before {
  background-image:
    repeating-linear-gradient(100deg,
      rgba(255, 255, 255, 0) 0px,
      rgba(255, 255, 255, .14) 92px,
      rgba(255, 253, 240, .04) 184px,
      rgba(255, 255, 255, .16) 276px,
      rgba(255, 255, 255, 0) 368px),
    radial-gradient(64% 48% at 40% 26%, rgba(255, 255, 250, .30) 0%, rgba(255, 255, 255, 0) 74%);
  mix-blend-mode: screen;
  opacity: .48;
  animation: blokemon-holo-rock 12s ease-in-out infinite alternate;
}

.blokemon-gym-card[data-holo] .art-viewport[data-placement="framed"]::after {
  background-image:
    linear-gradient(102deg,
      rgba(255, 255, 255, 0) 30%,
      rgba(255, 255, 255, .10) 41%,
      rgba(255, 255, 248, .44) 48%,
      rgba(255, 255, 255, .72) 50%,
      rgba(255, 255, 248, .44) 52%,
      rgba(255, 255, 255, .10) 59%,
      rgba(255, 255, 255, 0) 70%);
  mix-blend-mode: screen;
  opacity: .55;
  animation: blokemon-holo-glint 7s ease-in-out infinite alternate;
}

@keyframes blokemon-holo-rock {
  from { transform: translate3d(-5%, 0, 0); }
  to { transform: translate3d(5%, 0, 0); }
}

@keyframes blokemon-holo-glint {
  from { transform: translate3d(-15%, 0, 0); }
  to { transform: translate3d(15%, 0, 0); }
}

@media (prefers-reduced-motion: reduce) {
  .blokemon-gym-card[data-holo] .art-viewport[data-placement="framed"]::before,
  .blokemon-gym-card[data-holo] .art-viewport[data-placement="framed"]::after {
    animation: none;
  }
}

/* Imprint row: collector number sits left, the rarity word and mark stay right. */
.blokemon-gym-card .legal-row {
  grid-template-columns: 1fr auto auto;
  justify-content: stretch;
}

.blokemon-gym-card .collector-number {
  justify-self: start;
  font: 700 11px/12px var(--blokemon-face);
  letter-spacing: .05em;
}

/*
  Energy. A gold-foil header bar carries the ENERGY wordmark, the bound illustration drops
  back to a printed field behind the furniture, and the type symbol rides a printed sphere.
*/
.blokemon-gym-card:has([data-placement="field"]) .card-name {
  left: 25px;
  top: 36px;
  z-index: 6;
  width: 700px;
  height: 128px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(70, 52, 8, .88);
  border-radius: 3px;
  background: linear-gradient(180deg, #f8e79b 0%, #ecd063 26%, #e2bc41 54%, #cfa42e 82%, #bd9224 100%);
  box-shadow:
    inset 0 3px 0 rgba(255, 253, 226, .72),
    inset 0 -4px 6px rgba(92, 68, 12, .42),
    0 3px 5px rgba(48, 36, 6, .30);
  font-size: 92px;
  line-height: 124px;
  letter-spacing: .015em;
  text-transform: uppercase;
  color: #8a6f1e;
  text-shadow:
    0 -2px 0 rgba(255, 251, 214, .70),
    0 2px 0 rgba(74, 54, 8, .58),
    0 5px 7px rgba(52, 38, 6, .36);
}

.blokemon-gym-card .art-viewport[data-placement="field"] {
  left: 25px;
  top: 168px;
  z-index: 2;
  width: 700px;
  height: 856px;
  border-radius: 0 0 14px 14px;
  overflow: hidden;
  background: linear-gradient(180deg, var(--tt-cream) 0%, var(--tt-mid) 100%);
}

.blokemon-gym-card .art-viewport[data-placement="field"] img {
  object-fit: cover;
  opacity: .34;
  filter: saturate(.7) contrast(.9);
}

/* Sparkle and bloom sit over the backdrop so the field reads as printed stock, not flat colour. */
.blokemon-gym-card .art-viewport[data-placement="field"]::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background-image:
    conic-gradient(from 152deg at 50% 64%,
      rgba(255, 255, 246, 0) 0deg,
      rgba(255, 255, 246, .30) 13deg,
      rgba(255, 255, 246, 0) 28deg,
      rgba(255, 255, 246, 0) 92deg,
      rgba(255, 255, 246, .26) 105deg,
      rgba(255, 255, 246, 0) 120deg,
      rgba(255, 255, 246, 0) 212deg,
      rgba(255, 255, 246, .26) 226deg,
      rgba(255, 255, 246, 0) 240deg),
    radial-gradient(38% 24% at 50% 64%, rgba(255, 255, 244, .68) 0%, rgba(255, 255, 244, 0) 74%),
    radial-gradient(70% 40% at 50% 8%, var(--tt-glow) 0%, rgba(255, 255, 255, 0) 76%);
  opacity: .68;
}

/* Header badge: the reference disc measures 84px, its left edge 44px inside the bar. */
.blokemon-gym-card:has([data-placement="field"]) .main-type-icon {
  left: 69px;
  top: 58px;
  z-index: 7;
  width: 84px;
  height: 84px;
}

.blokemon-gym-card:has([data-placement="field"]) .main-type-icon .type-glyph {
  width: 50px;
  height: 50px;
}

/* The denomination is the card's large printed sphere. */
.blokemon-gym-card .denomination {
  position: absolute;
  left: 210px;
  top: 555px;
  z-index: 5;
  width: 330px;
  height: 330px;
  display: grid;
  place-items: center;
  border: 4px solid rgba(58, 44, 8, .82);
  border-radius: 50%;
  background:
    radial-gradient(circle at 34% 24%, rgba(255, 255, 236, .82) 0%, rgba(255, 255, 236, 0) 44%),
    radial-gradient(circle at 50% 108%, rgba(255, 250, 218, .40) 0%, rgba(255, 250, 218, 0) 40%),
    radial-gradient(circle at 50% 56%, var(--tt-icon) 0%, var(--tt-deep) 100%);
  box-shadow:
    inset 0 0 0 5px rgba(255, 253, 226, .50),
    inset 0 -16px 26px rgba(38, 28, 4, .40),
    0 16px 34px rgba(38, 28, 4, .42);
}

.blokemon-gym-card .denomination .type-glyph {
  width: 196px;
  height: 196px;
  filter: drop-shadow(0 3px 0 rgba(255, 252, 224, .30));
}
